// ROOFORA automation — shared helpers.
// Plain JavaScript with no imports: the build script pastes this file into
// n8n Code nodes, and the local tests load it the same way.

function str(v, max) {
  if (v === null || v === undefined) return '';
  const s = String(v).trim();
  return max ? s.slice(0, max) : s;
}

function firstName(fullName) {
  return str(fullName).split(/\s+/)[0] || 'there';
}

/** Escapes a value for use inside a single-quoted Airtable formula string. */
function af(value) {
  return "'" + String(value).replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'";
}

function list(text) {
  return str(text)
    .split(/[\n,;]+/)
    .map((s) => s.trim())
    .filter(Boolean);
}

function numberList(text, fallback) {
  const nums = list(text).map(Number).filter((n) => Number.isFinite(n) && n >= 0);
  return nums.length ? nums : fallback;
}

// ---------- time zones (Intl only, no libraries) ----------

/** Calendar parts of an instant as seen in a time zone. */
function zonedParts(date, tz) {
  const fmt = new Intl.DateTimeFormat('en-GB', {
    timeZone: tz,
    hourCycle: 'h23',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    weekday: 'short',
  });
  const p = {};
  for (const part of fmt.formatToParts(date)) p[part.type] = part.value;
  return {
    year: +p.year,
    month: +p.month,
    day: +p.day,
    hour: +p.hour,
    minute: +p.minute,
    second: +p.second,
    weekday: p.weekday, // 'Mon'
  };
}

/** UTC instant for a wall-clock time in a time zone (handles DST). */
function zonedToUtc(year, month, day, hour, minute, tz) {
  let guess = Date.UTC(year, month - 1, day, hour, minute);
  for (let i = 0; i < 3; i++) {
    const p = zonedParts(new Date(guess), tz);
    const shown = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute);
    const wanted = Date.UTC(year, month - 1, day, hour, minute);
    if (shown === wanted) break;
    guess += wanted - shown;
  }
  return new Date(guess);
}

function isValidTimeZone(tz) {
  try {
    new Intl.DateTimeFormat('en-GB', { timeZone: tz });
    return true;
  } catch (e) {
    return false;
  }
}

function hhmm(text, fallback) {
  const m = /^(\d{1,2}):(\d{2})$/.exec(str(text));
  if (!m) return fallback;
  const h = +m[1];
  const mi = +m[2];
  return h < 24 && mi < 60 ? { h, mi } : fallback;
}

/** Reads the opening-hours part of Settings into one object. */
function hoursFrom(settings) {
  const days = Array.isArray(settings['Opening Days']) && settings['Opening Days'].length
    ? settings['Opening Days']
    : ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'];
  return {
    tz: str(settings['Business Timezone']),
    days,
    open: hhmm(settings['Opening Time'], { h: 8, mi: 0 }),
    close: hhmm(settings['Closing Time'], { h: 17, mi: 0 }),
  };
}

function isOpenDay(date, hours) {
  return hours.days.includes(zonedParts(date, hours.tz).weekday);
}

/** Opening time on the n-th business day after `from` (n=0: same day if open). */
function businessDayAt(from, n, hours, at) {
  const time = at || hours.open;
  let p = zonedParts(from, hours.tz);
  let cursor = zonedToUtc(p.year, p.month, p.day, 12, 0, hours.tz);
  let remaining = n;
  for (let guard = 0; guard < 60; guard++) {
    if (isOpenDay(cursor, hours)) {
      if (remaining === 0) {
        p = zonedParts(cursor, hours.tz);
        return zonedToUtc(p.year, p.month, p.day, time.h, time.mi, hours.tz);
      }
      remaining--;
    }
    cursor = new Date(cursor.getTime() + 24 * 3600 * 1000);
  }
  throw new Error('No opening days configured');
}

/** True when the instant is inside opening hours on an opening day. */
function isWithinHours(date, hours) {
  if (!isOpenDay(date, hours)) return false;
  const p = zonedParts(date, hours.tz);
  const mins = p.hour * 60 + p.minute;
  return mins >= hours.open.h * 60 + hours.open.mi && mins <= hours.close.h * 60 + hours.close.mi;
}

/** Next moment the business is open (now, if open now). */
function nextOpenMoment(now, hours) {
  if (isWithinHours(now, hours)) return now;
  const p = zonedParts(now, hours.tz);
  const mins = p.hour * 60 + p.minute;
  // Closed day, or before opening on an open day: the next opening is the first open day (n=0). After closing: the following one.
  const sameOrNext = !isOpenDay(now, hours) || mins < hours.open.h * 60 + hours.open.mi;
  return businessDayAt(now, sameOrNext ? 0 : 1, hours);
}

function addDays(date, days) {
  return new Date(date.getTime() + days * 24 * 3600 * 1000);
}

function addMinutes(date, mins) {
  return new Date(date.getTime() + mins * 60 * 1000);
}

/** Customer-friendly date/time in the business time zone. */
function friendly(date, tz) {
  return new Intl.DateTimeFormat('en-GB', {
    timeZone: tz,
    weekday: 'long',
    day: 'numeric',
    month: 'long',
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
  }).format(date);
}

/** Adds a key to a newline-separated list field, without duplicates. */
function addToList(text, value) {
  const items = str(text).split('\n').map((s) => s.trim()).filter(Boolean);
  if (value && !items.includes(value)) items.push(value);
  return items.join('\n');
}

function hasInList(text, value) {
  return str(text).split('\n').map((s) => s.trim()).includes(value);
}

/** Google Calendar event IDs must use characters a-v and 0-9. */
function calendarEventId(recordId) {
  let hex = '';
  for (const ch of String(recordId)) hex += ch.charCodeAt(0).toString(16).padStart(2, '0');
  return 'rfi' + hex;
}

/** Plain-language Airtable error text from an HTTP response (fullResponse mode). */
function httpProblem(res) {
  const code = res && res.statusCode;
  const body = (res && res.body) || {};
  const err = body.error;
  const detail = typeof err === 'string' ? err : (err && (err.message || err.type)) || '';
  return 'HTTP ' + (code || 'no response') + (detail ? ': ' + String(detail).slice(0, 200) : '');
}

function ok(res) {
  return res && res.statusCode >= 200 && res.statusCode < 300;
}

/** A "needs help" item for the ROOFORA error workflow (never includes customer details). */
function problemOf(step, ref, leadId, problem, action, executionId) {
  return { source: 'handled', step, ref: ref || '', leadId: leadId || '', problem: String(problem || ''), action: action || '', executionId: executionId || '' };
}

// ROOFORA automation — plain-English problem reports for the error workflow.
// Depends on core.js. Never includes customer names, emails, phones or messages.

function scrub(text) {
  return str(text)
    .replace(/[^\s@]+@[^\s@]+\.[^\s@]+/g, '[email]')
    .replace(/\+?\d[\d\s().-]{6,}\d/g, '[number]')
    .replace(/(pat|key)[A-Za-z0-9._-]{10,}/g, '[secret]')
    .slice(0, 300);
}

const STEP_ADVICE = [
  [/airtable|save lead|load settings|load lead|find lead|update lead|record activity/i, 'Check the Airtable credential still works in n8n and that the ROOFORA base, table and field names match automation/airtable/schema.json. Then re-run the step from n8n Executions.'],
  [/gmail|email/i, 'Do not resend blindly: search Gmail › Sent for the message reference first. If it is not there, press the staff button again or send it by hand.'],
  [/calendar|book/i, 'Open the ROOFORA calendar and check whether the event exists before pressing Book again; pressing Book again is safe (it reuses the same event).'],
  [/photo|attachment/i, 'The enquiry is saved. Ask the customer to email the photos, or retry from the website within 2 hours.'],
  [/telegram/i, 'Check the Telegram bot credential and the ROOFORA chat ID.'],
];

function adviceFor(step, message) {
  for (const [re, advice] of STEP_ADVICE) if (re.test(step) || re.test(message)) return advice;
  return 'Open n8n › Executions, find the failed run and check the red step. Nothing will be retried automatically.';
}

/**
 * input: either an Error Trigger item ({ execution, workflow }) or a handled
 * problem ({ source: 'handled', step, ref, problem, action, severity }).
 */
function describeProblem(input, now) {
  const handled = input && input.source === 'handled';
  const exec = (input && input.execution) || {};
  const step = handled ? str(input.step) : str((exec.error && exec.error.node && exec.error.node.name) || exec.lastNodeExecuted || 'unknown step');
  const message = handled ? scrub(input.problem) : scrub(exec.error && exec.error.message);
  const ref = handled ? str(input.ref) : '';
  const workflow = handled ? 'ROOFORA Lead Manager' : str(input && input.workflow && input.workflow.name);
  const action = handled && str(input.action) ? str(input.action) : adviceFor(step, message);
  const runId = handled ? str(input.executionId) : str(exec.id);
  const title = (handled ? 'Needs your help: ' : 'Automation failed: ') + step + (ref ? ' (' + ref + ')' : '');
  const telegram = [
    '⚠️ ROOFORA — ' + title,
    'What happened: ' + (message || 'no error text'),
    'What to do: ' + action,
    runId ? 'n8n run: ' + runId : null,
  ].filter(Boolean).join('\n');
  return {
    throttleKey: step + '|' + ref + '|' + message.slice(0, 60),
    telegram,
    activity: {
      Activity: title.slice(0, 120),
      Type: 'Automation Problem',
      Status: 'Needs My Help',
      Details: 'Workflow: ' + workflow + '\nStep: ' + step + '\nProblem: ' + message + '\nRecommended action: ' + action,
      'Workflow Step': step,
      'n8n Execution': runId,
      'Created At': now.toISOString(),
    },
    leadRef: ref,
  };
}

/** Suppress identical alerts within 30 minutes (stops alert storms). */
function shouldAlert(store, key, now) {
  const last = store[key];
  store[key] = now.getTime();
  for (const k of Object.keys(store)) if (now.getTime() - store[k] > 24 * 3600e3) delete store[k];
  return !last || now.getTime() - last > 30 * 60e3;
}

// ---- node logic ----
const now = new Date();
const store = $getWorkflowStaticData('global');
store.alerts = store.alerts || {};
return $input.all().map((item) => {
  const raw = item.json.problem && typeof item.json.problem === 'object' ? item.json.problem : item.json;
  const d = describeProblem(raw, now);
  const fields = Object.assign({}, d.activity);
  if (raw.leadId && /^rec[A-Za-z0-9]{14}$/.test(raw.leadId)) fields.Lead = [raw.leadId];
  return { json: { alert: d.telegram, sendAlert: shouldAlert(store.alerts, d.throttleKey, now), method: 'POST', url: AT + 'Activity', body: { typecast: true, records: [{ fields }] } } };
});

